export const ReviewModal = ({ 
  isOpen, 
  title, 
  content, 
  onAccept, 
  onReject 
}: { 
  isOpen: boolean; 
  title: string; 
  content: string | object | null; 
  onAccept: () => void; 
  onReject: () => void; 
}) => {
  if (!isOpen) return null;

  const isObj = typeof content === 'object' && content !== null;

  return (
    <Modal isOpen={isOpen} onReject={onReject} onAccept={onAccept} title={title}>
      <div className="flex flex-col gap-2">
        {isObj ? (
          // @ts-ignore
          <JsonRecursive data={content} />
        ) : (
          <div>{content as string}</div>
        )}
      </div>
    </Modal>
  );
};
```

